# 1. Build dictionary mapping filename to its new absolute path
$dict = @{}
foreach ($f in $files) {
    if (-not $dict.ContainsKey($f.Name)) {
        $dict[$f.Name] = @($f.FullName)
    } else {
        $dict[$f.Name] += $f.FullName
    }
}

# 2. Fix links
$updatedCount = 0

foreach ($f in $files) {
    $content = Get-Content $f.FullName -Raw
    $originalContent = $content
    $modified = $false

    # Match links like [text](path.md)
    $matches = [regex]::Matches($content, '\]\(([^)]+\.md)\)')
    foreach ($m in $matches) {
        $link = $m.Groups[1].Value
        $cleanLink = $link -replace '^file:///', ''

        # Check if the target exists
        if ([System.IO.Path]::IsPathRooted($cleanLink)) {
            $targetPath = $cleanLink
        } else {
            $targetPath = Join-Path -Path $f.DirectoryName -ChildPath $cleanLink -Resolve -ErrorAction SilentlyContinue
            if (-not $targetPath) {
                $targetPath = Join-Path -Path $f.DirectoryName -ChildPath $cleanLink
            }
        }

        $exists = Test-Path $targetPath
        if (-not $exists) {
            # Extract filename from broken link
            $brokenFilename = [System.IO.Path]::GetFileName($cleanLink)

            # Lookup in dictionary
            if ($dict.ContainsKey($brokenFilename) -and $dict[$brokenFilename].Count -eq 1) {
                $newPath = $dict[$brokenFilename][0]
                # Format as file:/// with forward slashes
                $newLink = "file:///" + $newPath.Replace('\', '/')

                # Replace the exact link in the content
                $content = $content.Replace("]($link)", "]($newLink)")
                $modified = $true
                Write-Output "Fixed in $($f.Name): $link -> $newLink"
            } elseif ($dict.ContainsKey($brokenFilename) -and $dict[$brokenFilename].Count -gt 1) {
                Write-Output "WARNING: Multiple matches found for $brokenFilename in $($f.Name). Cannot safely replace."
            } else {
                Write-Output "WARNING: Could not find target file $brokenFilename referenced in $($f.Name)."
            }
        }
    }

    if ($modified) {
        Set-Content -Path $f.FullName -Value $content -NoNewline
        $updatedCount++
    }
}

Write-Output "Done. Updated $updatedCount files."

# Generate tree structure excluding the 'archive' folder
function Show-Tree {
    param(
        [string]$Path = '.',
        [string]$Prefix = ''
    )
    $items = Get-ChildItem -Path $Path | Where-Object { $_.Name -ne 'archive' }
    $count = $items.Count
    for ($i = 0; $i -lt $count; $i++) {
        $item = $items[$i]
        $isLast = ($i -eq $count - 1)
        $branch = if ($isLast) { '└── ' } else { '├── ' }
        Write-Output ($Prefix + $branch + $item.Name + if ($item.PSIsContainer) { '/' } else { '' })

        if ($item.PSIsContainer) {
            $newPrefix = $Prefix + (if ($isLast) { '    ' } else { '│   ' })
            Show-Tree -Path $item.FullName -Prefix $newPrefix
        }
    }
}

Show-Tree -Path .

function Show-Tree {
